import{_ as r,a0 as o,w as m,s as l,ao as p,I as d,a1 as i,A as n,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗） | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗） | LCTT (RAID) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗） | LCTT (RAID) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"RAID/Part 4 - Creating RAID 5 (Striping with Distributed Parity) in Linux","title":"在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗）","tag":"RAID","desc":""},"relativePath":"RAID/Part 4 - Creating RAID 5 (Striping with Distributed Parity) in Linux.md","filePath":"[post].md"}'),s={name:"RAID/Part 4 - Creating RAID 5 (Striping with Distributed Parity) in Linux.md"};function c(u,e,R,h,w,D){const a=o("Link");return m(),l("div",null,[e[17]||(e[17]=p('<h1 id="在-linux-下使用-raid-四-創建-raid-5-條帶化與分佈式奇偶校驗" tabindex="-1">在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗） <a class="header-anchor" href="#在-linux-下使用-raid-四-創建-raid-5-條帶化與分佈式奇偶校驗" aria-label="Permalink to “在 Linux 下使用 RAID（四）：創建 RAID 5（條帶化與分佈式奇偶校驗）”">​</a></h1><p>在 RAID 5 中，數據條帶化後存儲在分佈式奇偶校驗的多個磁盤上。分佈式奇偶校驗的條帶化意味着它將奇偶校驗信息和條帶化數據分佈在多個磁盤上，這樣會有很好的數據冗餘。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/setup-raid-5-in-linux.jpg" alt="Setup Raid 5 in CentOS"></p><p><em>在 Linux 中配置 RAID 5</em></p><p>對於此 RAID 級別它至少應該有三個或更多個磁盤。RAID 5 通常被用於大規模生產環境中，以花費更多的成本來提供更好的數據冗餘性能。</p><h4 id="什麼是奇偶校驗" tabindex="-1">什麼是奇偶校驗？ <a class="header-anchor" href="#什麼是奇偶校驗" aria-label="Permalink to “什麼是奇偶校驗？”">​</a></h4><p>奇偶校驗是在數據存儲中檢測錯誤最簡單的常見方式。奇偶校驗信息存儲在每個磁盤中，比如説，我們有4個磁盤，其中相當於一個磁盤大小的空間被分割去存儲所有磁盤的奇偶校驗信息。如果任何一個磁盤出現故障，我們可以通過更換故障磁盤後，從奇偶校驗信息重建得到原來的數據。</p><h4 id="raid-5-的優點和缺點" tabindex="-1">RAID 5 的優點和缺點 <a class="header-anchor" href="#raid-5-的優點和缺點" aria-label="Permalink to “RAID 5 的優點和缺點”">​</a></h4><ul><li>提供更好的性能。</li><li>支持冗餘和容錯。</li><li>支持熱備份。</li><li>將用掉一個磁盤的容量存儲奇偶校驗信息。</li><li>單個磁盤發生故障後不會丟失數據。我們可以更換故障硬盤後從奇偶校驗信息中重建數據。</li><li>適合於面向事務處理的環境，讀操作會更快。</li><li>由於奇偶校驗佔用資源，寫操作會慢一些。</li><li>重建需要很長的時間。</li></ul><h4 id="要求" tabindex="-1">要求 <a class="header-anchor" href="#要求" aria-label="Permalink to “要求”">​</a></h4><p>創建 RAID 5 最少需要3個磁盤，你也可以添加更多的磁盤，前提是你要有多端口的專用硬件 RAID 控制器。在這裏，我們使用“mdadm”包來創建軟件 RAID。</p><p>mdadm 是一個允許我們在 Linux 下配置和管理 RAID 設備的包。默認情況下沒有 RAID 的配置文件，我們在創建和配置 RAID 後必須將配置文件保存在一個單獨的文件 mdadm.conf 中。</p><p>在進一步學習之前，我建議你通過下面的文章去了解 Linux 中 RAID 的基礎知識。</p>',13)),d("ul",null,[d("li",null,[i(a,{href:"https://linux.cn/article-6085-1.html"},{default:n(()=>[...e[0]||(e[0]=[t("介紹 RAID 的級別和概念",-1)])]),_:1})]),d("li",null,[i(a,{href:"https://linux.cn/article-6087-1.html"},{default:n(()=>[...e[1]||(e[1]=[t("使用 mdadm 工具創建軟件 RAID 0 （條帶化）",-1)])]),_:1})]),d("li",null,[i(a,{href:"https://linux.cn/article-6093-1.html"},{default:n(()=>[...e[2]||(e[2]=[t("用兩塊磁盤創建 RAID 1（鏡像）",-1)])]),_:1})])]),e[18]||(e[18]=p(`<h4 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h4><pre><code>操作系統 :	CentOS 6.5 Final
IP 地址  :	192.168.0.227
主機名	 :	rd5.tecmintlocal.com
磁盤 1 [20GB]	 :	/dev/sdb
磁盤 2 [20GB]	 :	/dev/sdc
磁盤 3 [20GB]	 :	/dev/sdd
</code></pre><p>這是9篇系列教程的第4部分，在這裏我們要在 Linux 系統或服務器上使用三個20GB（名為/dev/sdb, /dev/sdc 和 /dev/sdd）的磁盤建立帶有分佈式奇偶校驗的軟件 RAID 5。</p><h3 id="第1步-安裝-mdadm-並檢驗磁盤" tabindex="-1">第1步：安裝 mdadm 並檢驗磁盤 <a class="header-anchor" href="#第1步-安裝-mdadm-並檢驗磁盤" aria-label="Permalink to “第1步：安裝 mdadm 並檢驗磁盤”">​</a></h3><p>1、 正如我們前面所説，我們使用 CentOS 6.5 Final 版本來創建 RAID 設置，但同樣的做法也適用於其他 Linux 發行版。</p><pre><code># lsb_release -a
# ifconfig | grep inet
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/CentOS-6.5-Summary.png" alt="Setup Raid 5 in CentOS"></p><p><em>CentOS 6.5 摘要</em></p><p>2、 如果你按照我們的 RAID 系列去配置的，我們假設你已經安裝了“mdadm”包，如果沒有，根據你的 Linux 發行版使用下面的命令安裝。</p><pre><code># yum install mdadm		[在 RedHat 系統]
# apt-get install mdadm 	[在 Debain 系統]
</code></pre><p>3、 “mdadm”包安裝後，先使用<code>fdisk</code>命令列出我們在系統上增加的三個20GB的硬盤。</p><pre><code># fdisk -l | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Install-mdadm-Tool.png" alt="Install mdadm Tool in CentOS"></p><p><em>安裝 mdadm 工具</em></p><p>4、 現在該檢查這三個磁盤是否存在 RAID 塊，使用下面的命令來檢查。</p><pre><code># mdadm -E /dev/sd[b-d]
# mdadm --examine /dev/sdb /dev/sdc /dev/sdd # 或
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Examine-Drives-For-Raid.png" alt="Examine Drives For Raid"></p><p><em>檢查 Raid 磁盤</em></p><p><strong>注意</strong>: 上面的圖片説明，沒有檢測到任何超級塊。所以，這三個磁盤中沒有定義 RAID。讓我們現在開始創建一個吧！</p><h3 id="第2步-為磁盤創建-raid-分區" tabindex="-1">第2步：為磁盤創建 RAID 分區 <a class="header-anchor" href="#第2步-為磁盤創建-raid-分區" aria-label="Permalink to “第2步：為磁盤創建 RAID 分區”">​</a></h3><p>5、 首先，在創建 RAID 前磁盤（/dev/sdb, /dev/sdc 和 /dev/sdd）必須有分區，因此，在進行下一步之前，先使用<code>fdisk</code>命令進行分區。</p><pre><code># fdisk /dev/sdb
# fdisk /dev/sdc
# fdisk /dev/sdd
</code></pre><h4 id="創建-dev-sdb-分區" tabindex="-1">創建 /dev/sdb 分區 <a class="header-anchor" href="#創建-dev-sdb-分區" aria-label="Permalink to “創建 /dev/sdb 分區”">​</a></h4><p>請按照下面的説明在 /dev/sdb 硬盤上創建分區。</p><ul><li>按 <code>n</code> 創建新的分區。</li><li>然後按 <code>P</code> 選擇主分區。選擇主分區是因為還沒有定義過分區。</li><li>接下來選擇分區號為1。默認就是1。</li><li>這裏是選擇柱面大小，我們沒必要選擇指定的大小，因為我們需要為 RAID 使用整個分區，所以只需按兩次 Enter 鍵默認將整個容量分配給它。</li><li>然後，按 <code>P</code> 來打印創建好的分區。</li><li>改變分區類型，按 <code>L</code>可以列出所有可用的類型。</li><li>按 <code>t</code> 修改分區類型。</li><li>這裏使用<code>fd</code>設置為 RAID 的類型。</li><li>然後再次使用<code>p</code>查看我們所做的更改。</li><li>使用<code>w</code>保存更改。</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sdb-Partition1.png" alt="Create sdb Partition"></p><p><em>創建 sdb 分區</em></p><p><strong>注意</strong>: 我們仍要按照上面的步驟來創建 sdc 和 sdd 的分區。</p><h4 id="創建-dev-sdc-分區" tabindex="-1">創建 /dev/sdc 分區 <a class="header-anchor" href="#創建-dev-sdc-分區" aria-label="Permalink to “創建 /dev/sdc 分區”">​</a></h4><p>現在，通過下面的截圖給出創建 sdc 和 sdd 磁盤分區的方法，或者你可以按照上面的步驟。</p><pre><code># fdisk /dev/sdc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sdc-Partition1.png" alt="Create sdc Partition"></p><p><em>創建 sdc 分區</em></p><h4 id="創建-dev-sdd-分區" tabindex="-1">創建 /dev/sdd 分區 <a class="header-anchor" href="#創建-dev-sdd-分區" aria-label="Permalink to “創建 /dev/sdd 分區”">​</a></h4><pre><code># fdisk /dev/sdd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-sdd-Partition1.png" alt="Create sdd Partition"></p><p><em>創建 sdd 分區</em></p><p>6、 創建分區後，檢查三個磁盤 sdb, sdc, sdd 的變化。</p><pre><code># mdadm --examine /dev/sdb /dev/sdc /dev/sdd
# mdadm -E /dev/sd[b-c]  # 或
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Changes-on-Partitions.png" alt="Check Partition Changes"></p><p><em>檢查磁盤變化</em></p><p><strong>注意</strong>: 在上面的圖片中，磁盤的類型是 fd。</p><p>7、 現在在新創建的分區檢查 RAID 塊。如果沒有檢測到超級塊，我們就能夠繼續下一步，在這些磁盤中創建一個新的 RAID 5 配置。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Raid-on-Partitions.png" alt="Check Raid on Partition"></p><p>*在分區中檢查 RAID *</p><h3 id="第3步-創建-md-設備-md0" tabindex="-1">第3步：創建 md 設備 md0 <a class="header-anchor" href="#第3步-創建-md-設備-md0" aria-label="Permalink to “第3步：創建 md 設備 md0”">​</a></h3><p>8、 現在使用所有新創建的分區(sdb1, sdc1 和 sdd1)創建一個 RAID 設備“md0”（即 /dev/md0），使用以下命令。</p><pre><code># mdadm --create /dev/md0 --level=5 --raid-devices=3 /dev/sdb1 /dev/sdc1 /dev/sdd1
# mdadm -C /dev/md0 -l=5 -n=3 /dev/sd[b-d]1   # 或
</code></pre><p>9、 創建 RAID 設備後，檢查並確認 RAID，從 mdstat 中輸出中可以看到包括的設備的 RAID 級別。</p><pre><code># cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Raid-Device.png" alt="Verify Raid Device"></p><p><em>驗證 Raid 設備</em></p><p>如果你想監視當前的創建過程，你可以使用<code>watch</code>命令，將 <code>cat /proc/mdstat</code> 傳遞給它，它會在屏幕上顯示且每隔1秒刷新一次。</p><pre><code># watch -n1 cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Monitor-Raid-Process.png" alt="Monitor Raid Process"></p><p><em>監控 RAID 5 構建過程</em></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Raid-Process-Summary.png" alt="Raid 5 Process Summary"></p><p><em>Raid 5 過程概要</em></p><p>10、 創建 RAID 後，使用以下命令驗證 RAID 設備</p><pre><code># mdadm -E /dev/sd[b-d]1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Raid-Level.png" alt="Verify Raid Level"></p><p><em>驗證 Raid 級別</em></p><p><strong>注意</strong>: 因為它顯示三個磁盤的信息，上述命令的輸出會有點長。</p><p>11、 接下來，驗證 RAID 陣列，假定包含 RAID 的設備正在運行並已經開始了重新同步。</p><pre><code># mdadm --detail /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Verify-Raid-Array.png" alt="Verify Raid Array"></p><p><em>驗證 RAID 陣列</em></p><h3 id="第4步-為-md0-創建文件系統" tabindex="-1">第4步：為 md0 創建文件系統### <a class="header-anchor" href="#第4步-為-md0-創建文件系統" aria-label="Permalink to “第4步：為 md0 創建文件系統###”">​</a></h3><p>12、 在掛載前為“md0”設備創建 ext4 文件系統。</p><pre><code># mkfs.ext4 /dev/md0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Create-md0-Filesystem.png" alt="Create md0 Filesystem"></p><p><em>創建 md0 文件系統</em></p><p>13、 現在，在<code>/mnt</code>下創建目錄 raid5，然後掛載文件系統到 /mnt/raid5/ 下，並檢查掛載點下的文件，你會看到 lost+found 目錄。</p><pre><code># mkdir /mnt/raid5
# mount /dev/md0 /mnt/raid5/
# ls -l /mnt/raid5/
</code></pre><p>14、 在掛載點 /mnt/raid5 下創建幾個文件，並在其中一個文件中添加一些內容然後去驗證。</p><pre><code># touch /mnt/raid5/raid5_tecmint_{1..5}
# ls -l /mnt/raid5/
# echo &quot;tecmint raid setups&quot; &gt; /mnt/raid5/raid5_tecmint_1
# cat /mnt/raid5/raid5_tecmint_1
# cat /proc/mdstat
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Mount-Raid-Device.png" alt="Mount Raid 5 Device"></p><p><em>掛載 RAID 設備</em></p><p>15、 我們需要在 fstab 中添加條目，否則系統重啓後將不會顯示我們的掛載點。編輯 fstab 文件添加條目，在文件尾追加以下行。掛載點會根據你環境的不同而不同。</p><pre><code># vim /etc/fstab

/dev/md0                /mnt/raid5              ext4    defaults        0 0
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Raid-Device-Automount.png" alt="Raid 5 Automount"></p><p><em>自動掛載 RAID 5</em></p><p>16、 接下來，運行<code>mount -av</code>命令檢查 fstab 條目中是否有錯誤。</p><pre><code># mount -av
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Check-Fstab-Errors.png" alt="Check Fstab Errors"></p><p><em>檢查 Fstab 錯誤</em></p><h3 id="第5步-保存-raid-5-的配置" tabindex="-1">第5步：保存 Raid 5 的配置 <a class="header-anchor" href="#第5步-保存-raid-5-的配置" aria-label="Permalink to “第5步：保存 Raid 5 的配置”">​</a></h3><p>17、 在前面章節已經説過，默認情況下 RAID 沒有配置文件。我們必須手動保存。如果此步中沒有跟隨不屬於 md0 的 RAID 設備，它會是一些其他隨機數字。</p><p>所以，我們必須要在系統重新啓動之前保存配置。如果配置保存它在系統重新啓動時會被加載到內核中然後 RAID 也將被加載。</p><pre><code># mdadm --detail --scan --verbose &gt;&gt; /etc/mdadm.conf
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/11/Save-Raid-5-Configuration.png" alt="Save Raid 5 Configuration"></p><p><em>保存 RAID 5 配置</em></p><p>注意：保存配置將保持 md0 設備的 RAID 級別穩定不變。</p><h3 id="第6步-添加備用磁盤" tabindex="-1">第6步：添加備用磁盤 <a class="header-anchor" href="#第6步-添加備用磁盤" aria-label="Permalink to “第6步：添加備用磁盤”">​</a></h3><p>18、 備用磁盤有什麼用？它是非常有用的，如果我們有一個備用磁盤，當我們陣列中的任何一個磁盤發生故障後，這個備用磁盤會進入激活重建過程，並從其他磁盤上同步數據，這樣就有了冗餘。</p><p>更多關於添加備用磁盤和檢查 RAID 5 容錯的指令，請閲讀下面文章中的第6步和第7步。</p>`,96)),d("ul",null,[d("li",null,[i(a,{href:"http://www.tecmint.com/create-raid-6-in-linux/"},{default:n(()=>[...e[3]||(e[3]=[t("在 RAID 5 中添加備用磁盤",-1)])]),_:1})])]),e[19]||(e[19]=d("h3",{id:"結論",tabindex:"-1"},[t("結論 "),d("a",{class:"header-anchor",href:"#結論","aria-label":"Permalink to “結論”"},"​")],-1)),e[20]||(e[20]=d("p",null,"在這篇文章中，我們已經看到了如何使用三個磁盤配置一個 RAID 5 。在接下來的文章中，我們將看到如何故障排除並且當 RAID 5 中的一個磁盤損壞後如何恢復。",-1)),e[21]||(e[21]=d("hr",null,null,-1)),d("p",null,[e[5]||(e[5]=t("via: ",-1)),i(a,{href:"http://www.tecmint.com/create-raid-5-in-linux/"},{default:n(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/create-raid-5-in-linux/",-1)])]),_:1})]),d("p",null,[e[9]||(e[9]=t("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/babinlonston/"},{default:n(()=>[...e[6]||(e[6]=[t("Babin Lonston",-1)])]),_:1}),e[10]||(e[10]=t(" 譯者：",-1)),i(a,{href:"https://github.com/strugglingyouth"},{default:n(()=>[...e[7]||(e[7]=[t("strugglingyouth",-1)])]),_:1}),e[11]||(e[11]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[14]||(e[14]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原創翻譯，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[13]||(e[13]=[t("Linux中國",-1)])]),_:1}),e[16]||(e[16]=t(" 榮譽推出",-1))])])}const f=r(s,[["render",c]]);export{g as __pageData,f as default};
